    public static function cargarBonPen($params)
    {
        $start = $params['start'];
        $limit = $params['limit'];

        $idtrabajooperarios = $params['idtrabajooperarios'];
        if (!$idtrabajooperarios) {
            return [];
        }
        $conn = Zend_Registry::get('conexion');

        $result = $conn->fetchAll("
        select bp.*
            , count(*) over() as cantidad
        from mod_logtaller.dat_bonificacionpenalizacion bp
        inner join mod_logtaller.dat_trabajooperarios top on(top.idtrabajooperarios = bp.idtrabajooperarios)
        where bp.idtrabajooperarios = $idtrabajooperarios
        order by bp.idestado desc, bp.idbonificacionpenalizacion desc
        LIMIT $limit
        OFFSET $start
        ");

        return $result;
    }

    public static function hayBonActiva($idtrabajooperarios)
    {
        $limit = 1;
        if (!$idtrabajooperarios) {
            return false;
        }
        $conn = Zend_Registry::get('conexion');

        $result = $conn->fetchAll("
        select bp.*
        from mod_logtaller.dat_bonificacionpenalizacion bp
        where bp.idtrabajooperarios = $idtrabajooperarios and idestado = 1
        LIMIT $limit
        ");

        if (count($result)) {
            return true;
        } else {
            return false;
        }
    }

    public static function saveBonPen($objBonPen)
    {
        try {
            if ($objBonPen->idbonificacionpenalizacion) {
                $obj = Doctrine::getTable('DatBonPen')
                    ->find($objBonPen->idbonificacionpenalizacion);
            }
            else {
                $obj = new DatBonPen();
            }

            if ($objBonPen->idtrabajooperarios) {
                $obj->idtrabajooperarios = $objBonPen->idtrabajooperarios;
            }
            if (is_numeric($objBonPen->idestado)) {
                $obj->idestado = $objBonPen->idestado;
            }
            if (is_numeric($objBonPen->idtipobonpen)) {
                $obj->idtipobonpen = $objBonPen->idtipobonpen;
            }
            if (is_numeric($objBonPen->idbonpen)) {
                $obj->idbonpen = $objBonPen->idbonpen;
            }
            if (is_numeric($objBonPen->bonpen)) {
                $obj->bonpen = $objBonPen->bonpen;
            }
            if (is_numeric($objBonPen->importebase)) {
                $obj->importebase = $objBonPen->importebase;
            }
            if ($objBonPen->observacion || $objBonPen->observacion === '') {
                $obj->observacion = $objBonPen->observacion;
            }
            if ($objBonPen->observacioncancel || $objBonPen->observacioncancel === '') {
                $obj->observacioncancel = $objBonPen->observacioncancel;
            }
            if ($objBonPen->iduser) {
                $obj->iduser = $objBonPen->iduser;
            }
            if ($objBonPen->idusercancel) {
                $obj->idusercancel = $objBonPen->idusercancel;
            }

            $obj->save();
            return $obj->idbonpen;
        } catch (Doctrine_Exception $e) {
            throw $e;
        }
